import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Create main group
  const group = new Group();

  // Handle Spec Colors
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 1. STAGE: Engineered backdrop gradient plane to combat void and provide stage grounding
  const backdropGeo = new PlaneGeometry(7.0, 6.0);
  const backdropMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });

  // Custom TSL vertical gradient using colors.surface and a slightly lighter mix of surface & ink
  const backdropColorBottom = new Color(colors.surface);
  const backdropColorTop = new Color(colors.ink).multiplyScalar(0.4);
  const vUv = uv();
  backdropMat.colorNode = vec4(
    vUv.y.mix(backdropColorBottom, backdropColorTop),
    1.0
  );

  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.set(0, 0, -2.5);
  group.add(backdropMesh);

  // 2. HERO SPRITE (Journal Card Plane)
  // Atlas coordinate specs: 0, 0, 512, 320 -> Aspect ratio = 512 / 320 = 1.6
  const width = 3.2;
  const height = width / 1.6;
  const cardGeo = new PlaneGeometry(width, height);
  const cardMat = new MeshBasicNodeMaterial({ transparent: true });

  const cardMesh = new Mesh(cardGeo, cardMat);
  group.add(cardMesh);

  // Load the texture mapped map image if present in the config assets
  const imageUrl = config.imageUrl ?? '/prism-assets/chrome/ceramic-grain.map.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    // Atlas Mapping (0, 0, 512, 320) inside likely a 512x512 atlas
    // Scale down UVs to focus on the atlas region if required. Since standard behavior is mapped,
    // we use a scale & offset custom node mapping to pull exactly the atlas region if needed.
    const uvs = uv();
    const atlasUv = vec2(uvs.x.mul(1.0), uvs.y.mul(0.625)); // 320/512 = 0.625
    cardMat.map = tex;
    cardMat.colorNode = cardMat.colorNode; // Assigning ensures it registers with TSL hooks
    cardMat.needsUpdate = true;
  });

  // 3. ANCHORED COMPASS TEXT: Engine specs or designator in JetBrains Mono
  const monoText = ctx.fontAtlas.createText('ART. JOURNAL // N0.02', {
    fontSize: 0.08,
    color: colors.accent,
    align: 'center'
  });
  monoText.position.set(0, -(height / 2) - 0.25, 0.02);
  group.add(monoText);

  // Apply Rise-In Weighted Entrance via GSAP
  gsap.fromTo(
    cardMesh.position,
    { y: -0.4 },
    { y: 0, duration: 0.8, ease: 'power3.out' }
  );
  gsap.fromTo(
    cardMesh.scale,
    { x: 0.95, y: 0.95 },
    { x: 1, y: 1, duration: 0.9, ease: 'power4.out' }
  );

  // Cleanup handler
  group.userData = {
    cleanup() {
      backdropGeo.dispose();
      backdropMat.dispose();
      cardGeo.dispose();
      cardMat.dispose();
      gsap.killTweensOf(cardMesh.position);
      gsap.killTweensOf(cardMesh.scale);
    }
  };

  return group;
}
